-- Deterministic demo data; not real tram routes or passenger counts.
BEGIN;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, color=EXCLUDED.color;
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, lat=EXCLUDED.lat, lon=EXCLUDED.lon;
ON CONFLICT (route_id, direction_id, sequence) DO UPDATE SET stop_id=EXCLUDED.stop_id;
ON CONFLICT (route_id, stop_id, direction_id, timestamp, horizon, forecast_origin, model_version) DO UPDATE SET resolution=EXCLUDED.resolution, predicted_load=EXCLUDED.predicted_load, lower_bound=EXCLUDED.lower_bound, upper_bound=EXCLUDED.upper_bound, value_unit=EXCLUDED.value_unit, aggregation=EXCLUDED.aggregation, is_mock=EXCLUDED.is_mock, interval_level=EXCLUDED.interval_level;
COMMIT;
